113	    public static function create(int $userId, float $maxWin, ?int $gameId = null, ?int $userBonusId = null, ?int $freespinId = null, bool $isActive = false): self
114	    {
115	        $model = new self();
116	        $model->user_id = $userId;
117	        $model->game_id = $gameId;
118	        $model->user_bonus_id = $userBonusId;
119	        $model->max_win = $maxWin;
120	        $model->left_until_max_amount = $maxWin;
121	        $model->freespin_id = $freespinId;
122	        $model->active = $isActive;
123	        if (!$model->save()) {
124	            throw new Exception(json_encode($model->getErrors(), JSON_THROW_ON_ERROR));
125	        }
126	        $model->refresh();
127	
128	        if ($isActive) {
129	            /** @var self[] $maxWins */
130	            $maxWins = self::find()->where(['active' => true, 'game_id' => $gameId, 'user_id' => $userId])->all();
131	            foreach ($maxWins as $maxWinModel) {
132	                if ($model->id === $maxWinModel->id) {
133	                    continue;
134	                }
135	                $maxWinModel->active = false;
136	                $maxWinModel->save();
137	            }
138	        }
139	        return $model;
