308	     */
309	    public static function syncLeftUntilMaxAmountCache(int $userId, ?int $userBonusId = null, ?int $gameId = null, ?int $freespinId = null): void
310	    {
311	        $value = static::getLeftUntilMaxAmount(
312	            userId: $userId,
