    public static function runQueue(array $gameAction, User $user): void
    {
        try {
            if (isset(Yii::$app->params['users_for_go_worker']) && (in_array('*',Yii::$app->params['users_for_go_worker']) || in_array($user->id,Yii::$app->params['users_for_go_worker']))) {
                Yii::$app->queueGameGo->push(new \common\jobs\GameProcess(['game_action' => $gameAction]));
                if (!YII_ENV_PROD) Logger::writeInfo(__METHOD__ . '::' . 'Run GO Queue');
            }else{
                Yii::$app->queueGame->push(new \common\jobs\GameProcess(['game_action' => $gameAction]));
                if (!YII_ENV_PROD) Logger::writeInfo(__METHOD__ . '::' . 'Run PHP Queue');
            }
        } catch (\Exception $ex) {
            BackgroundGameProcess::processingGameTransaction($gameAction);
            if (!YII_ENV_PROD) Logger::writeInfo(__METHOD__ . '::' . 'Run NOW');
        }
    }

    /**
     * @go-parity internal/processor/freespin.go syncMaxWinCache
     *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
     */
    private static function updateMaxWin(UserBonus|Freespin $model): void
    {
        $mutex = new RedisMutex(['redis' => Yii::$app->redis, 'expireTime' => 2]);
        $key = __CLASS__ . '_max_win' . $model->id;
        try {
            if ($mutex->acquire($key)) {
                $model->maxWinUserBonus->refresh();
                MaxWinUserBonus::syncLeftUntilMaxAmountCache(
                    userId: $model->getUserId(),
                    userBonusId: ($model instanceof UserBonus) ? $model->id : null,
                    gameId: ($model instanceof Freespin) ? $model->game->id : null,
                    freespinId: ($model instanceof Freespin) ? $model->id : null,
                );
                $mutex->release($key);
            } else {
                usleep(1_000_000 * 0.05);
                self::updateMaxWin($model);
            }
        } catch (\Throwable $e) {
            $mutex->release($key);
            Logger::writeError("BackgroundGameProcess::updateMaxWin[{$model->id}]:" . $e->getMessage() . PHP_EOL . $e->getTraceAsString());
        }
    }

    /**
     * @go-parity internal/processor/game_processor.go processGameAction, processBet; internal/processor/freespin.go processFreespin
     *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
     */
    public static function processingGameTransaction($game_action)
    {
        $game = Game::find()->where(['slug'=>$game_action['game_uuid']])->one();
        $user = User::find()->where(['uid' => $game_action['player_id']])->one();

        if(empty($game) ){
            return true;
        }

        if (!YII_ENV_PROD){
            Logger::writeToLoki(json_encode([
                    'userId' => $user ? $user->id : null,
                    'gameId' => $game->id,
                    'data' => $game_action,
                ]),'__TEST__GR_CALLBACK');
        }

        if($game_action['type'] === 'freespin'){
            if (!isset($game_action['freespin_id'])){
                Logger::writeInfo('processingGameTransaction freespin_id empty: SessionId:'.$game_action['session_id']);
                return false;
            }

            /** @var Freespin $freespin */
            $freespin = Freespin::find()->where(['freespin_id' => $game_action['freespin_id']])->one();
            if (!$freespin) {
                Logger::writeInfo('processingGameTransaction Freespin not found: SessionId:'.$game_action['session_id']);
                return false;
            }
            /** @var UserBonus $userBonus */
            $userBonus = $freespin->userBonus;

            if (!$userBonus) {
                if ($freespin->hasMaxWin()) {
                    self::updateMaxWin($freespin);
                    $transaction = Yii::$app->db->beginTransaction();
                    $wallet = Wallet::find()->where(['user_id'=>$user->id,'currency'=>$game_action['currency']])->one();
                    try {
                        $amount = $game_action['amount'];
                        if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
                        $amount = $freespin->maxWinUserBonus->getAllowedAmountToDep($amount);
                        if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
                        $wallet->deposit($amount);
                        $transaction->commit();
                    } catch (Exception $ex) {
                        $transaction->rollBack();
                        Logger::writeError('Bonus confirm error: user_bonusId:'.$userBonus->id .' userId:'.$userBonus->user_id .' CAUSE: '.$ex->getMessage());
                        throw $ex;
                    }
                }
                //якщо нема бонусу , то це може бути промокод просто з фс, без вейджеру - вони в іншій таблиці зберігаються
                $promocod = $freespin->bonusCodLog;
                if ($promocod && ($freespin->isEnded())) {
                    $promocod->used = true;
                    $promocod->save();
                }
                return true;
            }

            if(!$userBonus->isActive() || $userBonus->status == \common\models\UserBonus::STATUS_END || $userBonus->status == \common\models\UserBonus::STATUS_REFUSE){
                return false;
            }

            if($game_action['action'] === 'win'){
                $amount = $game_action['amount'];
//                $amount = ($userBonus->maxWinUserBonus) ? $userBonus->maxWinUserBonus->getAllowedAmountToDep($amount) : $amount;

                if($userBonus->is_wager){
                    //По ТЗ Если это бонус ФС вейджерный относительный(процентный) то вейджер начисляем динамически от выигрыша
                    $addAmount = $amount;
                    if ($userBonus->hasMaxWin()) {
                        $maxWinBonus = $userBonus->maxWinUserBonus;
                        $addAmount = $maxWinBonus ? $maxWinBonus->getAllowedAmountToDep($amount) : $amount;
                    }
                    if($userBonus->wagerTypePercent()){
                        //вейджер може бути меншим від виграшу по максвін
                        $wagerSum = $addAmount * $userBonus->amount_percent_wager/100;
                        $userBonus->wager = $userBonus->wager + $wagerSum;
                        $userBonus->amount_wager = $userBonus->amount_wager + $wagerSum;
                    }
                    $userBonus->amount = $userBonus->amount + $addAmount;

                }

                if ($userBonus->hasMaxWin()) {
                    self::updateMaxWin($userBonus);
                    if (!$userBonus->is_wager && !$freespin->isEnded()) {
                        $transaction = Yii::$app->db->beginTransaction();
                        $wallet = Wallet::find()->where(['user_id'=>$user->id,'currency'=>$game_action['currency']])->one();
                        try {
                            $amount = $game_action['amount'];
                            if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
                            $amount = $userBonus->maxWinUserBonus->getAllowedAmountToDep($amount);
                            if (!YII_ENV_PROD) Logger::writeInfo("__TEST__GR_CALLBACK [" . __LINE__ . "]:" . json_encode(['amount' => $amount]));
                            $wallet->deposit($amount);
                            $transaction->commit();
                        } catch (Exception $ex) {
                            $transaction->rollBack();
                            Logger::writeError('Bonus confirm error: user_bonusId:'.$userBonus->id .' userId:'.$userBonus->user_id .' CAUSE: '.$ex->getMessage());
                            throw $ex;
                        }
                    }
                }
            }

            // @infection-ignore-all блок прежний и в common/unit без БД не исполняется; новое решение в нём — FreespinEndCredit::isDue (unit-тесты)
            if($freespin->isEnded($game_action['time'])){
                if ($userBonus->is_wager && $freespin->total_win > 0) {
                    Notice::sendNotice($user->id, Notice::LOGIC_FS_WAGER_ACTIVE,
                        ['amount' => $freespin->total_win, 'wager_amount' => $userBonus->wager]);
                }
                if(!$userBonus->is_wager){
                    // сумма, зачисленная при активации (accrual_time), второй раз не зачисляется (DBR-009, DBR-011)
                    if(FreespinEndCredit::isDue($userBonus->amount, $userBonus->accrual_time)){
                        $transaction = Yii::$app->db->beginTransaction();
                        $wallet = Wallet::find()->where(['user_id'=>$user->id,'currency'=>$userBonus->currency])->one();
                        try {
                            $wallet->deposit($userBonus->getRealAmount());
                            $userBonus->accrual_time = time();
                            $userBonus->status = UserBonus::STATUS_END;
                            $userBonus->save();
                            $transaction->commit();
                        } catch (Exception $ex) {
                            $transaction->rollBack();
                            Logger::writeError('Bonus confirm error: user_bonusId:'.$userBonus->id .' userId:'.$userBonus->user_id .' CAUSE: '.$ex->getMessage());
                            throw $ex;
                        }
                    }else{
                        $userBonus->closeBonus();
                    }
                } elseif ($userBonus->checkForUpdateWager($game_action['time']) && $userBonus->wager <= 0) {
                    //якщо вейджер 0 - закриваємо бонус
                    $userBonus->save(false);
                    $userBonus->closeWagerBonus();
                }
            }

            $userBonus->save(false);

        }
        elseif ($game_action['action'] === 'bet')
        {


            if (!YII_ENV_PROD) {
                $tmp = $userBonus = UserBonus::find()->where(['user_id'=>$user->id,'status'=>UserBonus::STATUS_ACTIVE,'is_wager'=>true,'currency'=>$game_action['currency']])
                    ->andWhere(['>=','wager', 0])
                    ->andWhere('amount_wager IS NOT NULL')
                    ->andWhere(['>', 'amount_wager', 0.00])
                    ->orderBy('id DESC')->one();
                Logger::writeInfo('__TEST__GR_CALLBACK: [' . __LINE__ . '] ' . json_encode($tmp));
                unset($tmp);
            }
            if ($userBonus = UserBonus::find()->where(['user_id'=>$user->id,'status'=>UserBonus::STATUS_ACTIVE,'is_wager'=>true,'currency'=>$game_action['currency']])
                ->andWhere(['>=','wager', 0])
                ->andWhere('amount_wager IS NOT NULL')
                ->andWhere(['>', 'amount_wager', 0.00])
                ->orderBy('id DESC')->one()) {

                if (!YII_ENV_PROD) Logger::writeInfo('__TEST__GR_CALLBACK: [' . __LINE__ . '] ' . json_encode([
                        'time' => $game_action['time'],
                        'checkForUpdateWager' => $userBonus->checkForUpdateWager($game_action['time']),
                        'considerWager' => $game->considerWager(),
                    ]));
                if ($userBonus->checkForUpdateWager($game_action['time']) && !$game->considerWager()) {
                    //если игра в групе не считать вейджер, то пропускаем
                    //перевірка відбувається в фоні, тому може бути затримка
                    if (!YII_ENV_PROD) Logger::writeInfo('__TEST__GR_CALLBACK: [' . __LINE__ . '] ' . 'update wager');
                    $userBonus->updateWagerByTime($game_action['amount'], $game_action['time']);
                }
            }

