 * @go-parity internal/models/user_bonus.go loadParent
 *   Повторено в Go-воркері go_game_worker: змінюєш поведінку — онови Go і scripts/go-parity.json.
 */
public function getBonus()
{
    if (!$this->is_promocod) {
        return $this->hasOne(Bonus::class, ['id' => 'bonus_id']);
    }
    return null;
}

/**
 * Связь только для жадной загрузки бонуса списком: `with('bonus')` строит связь по
 * первой строке, и если это промокод, getBonus() даёт null и запрос падает.
 * Загруженное раскладывается в `bonus` — см. populateRelation().
 *
 * @infection-ignore-all связь ActiveRecord, в common/unit БД нет
 * @codeCoverageIgnore
 */
public function getBonusEager(): ActiveQuery
{
    return $this->hasOne(Bonus::class, ['id' => 'bonus_id']);
}

/**
 * `bonus` заполняется из `bonusEager` с тем же условием, что в getBonus(): у промокода
 * bonus_id указывает на bonus_cod, чужой Bonus с тем же id ему не достаётся.
 *
 * @infection-ignore-all хук ActiveRecord: какие связи заполнить — UserBonusRelations::mirrored (unit-тесты)
 * @codeCoverageIgnore
 */
public function populateRelation($name, $records)
{
    parent::populateRelation($name, $records);
    foreach (UserBonusRelations::mirrored((string)$name, (bool)$this->is_promocod, $records) as $relation => $related) {
        parent::populateRelation($relation, $related);
    }
}

