/**
 * Коробка гравця, що чекає на депозит, за bonus.id — для каси, відкритої під бонус
 * зі списку (мобільний клієнт знає bonus.id, а не user_bonus.id). null — у гравця
 * немає закритої коробки цього бонуса.
 *
 * @codeCoverageIgnore вибірка з БД — рішення про очікування депозиту покрите юнітами
 *                     BonusDepositRangeHelper::isWaitingForDeposit()
 * @infection-ignore-all див. вище
 */
public function findPendingBoxByBonus(User $user, int $bonusId): ?UserBonus
{
    if ($bonusId <= 0) {
        return null;
    }

    /** @var UserBonus|null $box */
    $box = UserBonus::find()
        ->innerJoin(Bonus::tableName(), 'bonus.id = user_bonus.bonus_id')
        ->where([
            'user_bonus.user_id' => $user->id,
            'user_bonus.bonus_id' => $bonusId,
            'user_bonus.status' => UserBonus::STATUS_NEW,
            'user_bonus.wait_dep' => true,
            'bonus.event' => Bonus::EVENT_GIFTBOX_DEP,
        ])
        ->orderBy(['user_bonus.id' => SORT_DESC])
        ->one();

    return $box && $box->isWaitingForDeposit() ? $box : null;
}

/**
