 * а логіка навколо (createFreespin, cancelActiveWager) лишається під тестами.
 *
 * @codeCoverageIgnore тонкий адаптер без розгалужень: Game::findOne
 * @infection-ignore-all див. вище
 */
protected function findGame($gameId): ?Game
{
    return Game::findOne($gameId);
}

/**
 * @codeCoverageIgnore тонкий адаптер без розгалужень: Freespin::canCreateMoreSimilar
 * @infection-ignore-all див. вище
 */
protected function canCreateMoreFreespins($slug, string $userUid)
{
    return Freespin::canCreateMoreSimilar($slug, $userUid);
}

/**
 * Мьютекс на гравця, щоб паралельні кліки не зробили дубль фріспінів; живе 60 с.
 *
 * @codeCoverageIgnore тонкий адаптер без розгалужень над Redis
 * @infection-ignore-all див. вище
 */
protected function acquireFreespinMutex($userId): bool
{
    $mutex = new RedisMutex(['redis' => Yii::$app->redis, 'expireTime' => 60]);

    return $mutex->acquire('activate_freespin_' . $userId);
}

/**
 * @codeCoverageIgnore тонкий адаптер без розгалужень: Freespin::createFreeSpin
 * @infection-ignore-all див. вище
 */
protected function createFreespinRecord($userUid, $currency, $gameSlug, $denomination, $bet, $quantity, $bonusId, $event)
{
    return Freespin::createFreeSpin($userUid, $currency, $gameSlug, $denomination, $bet, $quantity, $bonusId, $event);
}

