     */
    public function createFsForUser(User $user, int $count)
    {
        try {
            $setting = $this->getSettingAsArray();
            if (empty($setting)) {
                return false;
            }
            if (!isset($setting['gameId']) || !isset($setting['denominations']) || !isset($setting['betId'])) {
                return false;
            }
            if (!isset($setting['currency']) ) {
                $currency = 'UAH';
            }else{
                $currency = $setting['currency'];
            }

            $game = \common\models\Game::findOne($setting['gameId']);
            if (!$game) {
                return false;
            }

            $denominations = $setting['denominations'];
            $betId = $setting['betId'];
            if (Freespin::canCreateMoreSimilar($game->slug, $user->uid)) {
                $freespinId = Freespin::createFreeSpin(
                    $user->uid,
                    $currency,
                    $game->slug,
                    $denominations,
                    $betId,
                    $count,
                    null,
                    Freespin::EVENT_TOURNAMENT_WIN
                );
                return $freespinId;
            }
            return false;
        } catch (\Exception $e) {
            echo $e->getMessage();
            return false;
        }
    }

}

