        $bonus->event
    );
    if (!$freespinId) {
        $this->logError('[GiftBoxDep] cannot create freespin for user_bonus ' . $box->id);
        $this->error = self::ERROR_FS_FAILED;
        return false;
    }

    $box->freespin_id = $freespinId;
    $box->to = $this->freespinValidUntil($freespinId);
    $box->accepted_time = time();
