/**
 * ФС видаються так само, як решта нагород, — рядком user_bonus у «Моїх бонусах».
 *
 * Freespin::createFreeSpin() тут НЕ використовується: це примітив АКТИВАЦІЇ (останній
 * крок штатного шляху — partner/api MyBonusController::actionActivateBonus). Він створює
 * спіни в провайдера, але рядка user_bonus не має, а вейджер ФС живе саме в ньому:
 * зв'язок «спіни → бонус» — це user_bonus.freespin_id, по ньому колбек виграшу бере
 * $freespin->userBonus і вирішує, вести виграш у вейджер чи на реальний баланс
 * (grcallback SiteController). Без рядка user_bonus зв'язку немає — тож ФС із
 * налаштованим відіграшем прилітали гравцю зовсім без відіграшу.
 *
 * Видача — це Bonus::prepareUserBonus(), як і в решти типів: рядок user_bonus зі своїм
 * вейджером (ФС без вейджера так само лишається без нього) і строком життя, статус
 * AVAILABLE. Спіни в провайдера створить активація, коли гравець сам забере нагороду, —
 * це й загальне правило лестниці (див. moveRewardToAvailable).
 *
 * Два гейти — до видачі, бо без них нагорода була б мертвою: гравець не зможе її
 * активувати ні без гри (freespin_setting['gameId']), ні з подією, якої немає в
 * ALL_EVENT_FOR_ACTIVATE_BONUS (обидва — MyBonusController на сайті та в API).
 */
private function grantFreeSpin(Bonus $bonus, User $user): ?array
{
    if (!$bonus->getGame()) {
        Logger::writeError('[ComebackLadder] FS bonus ' . $bonus->id . ' has no game');
        return null;
    }
    if (!in_array($bonus->event, Bonus::ALL_EVENT_FOR_ACTIVATE_BONUS, true)) {
        Logger::writeError('[ComebackLadder] FS bonus ' . $bonus->id
            . ' has non-activatable event ' . var_export($bonus->event, true));
        return null;
    }

    $userBonusId = $bonus->prepareUserBonus($user->id);
    if (!$userBonusId) {
        return null;
    }
    $this->moveRewardToAvailable($this->findUserBonus($userBonusId));

    return [
        // тип лишається 'fs': за ним аналітика відділяє ФС від грошових грантів,
        // а amount — кількість спінів (див. ComebackLadderPresenter::grantText)
        'reward_type' => 'fs',
        'user_bonus_id' => (int)$userBonusId,
        'amount' => $bonus->countFs !== null ? (float)$bonus->countFs : null,
    ];

