/**
 * Активація виграного призу гравцем: фріспіни створюються тут, вейджерні призи
 * переводяться в активний стан, приз «на наступний депозит» починає чекати поповнення.
 *
 * @return bool false — причина в $this->error
 */
public function activatePrize(UserBonus $box): bool
{
    $this->error = null;
    $bonus = $box->bonus;
    $user = $box->user;
    if (!$bonus || !$user) {
        $this->error = self::ERROR_NOT_READY;
        return false;
    }

    $prize = $box->setting['prize'] ?? null;

    if ($prize === Bonus::GIFT_PRIZE_FS_WAGER && !$this->createFreespin($box, $bonus, $user)) {
        return false;
    }

    $transaction = Yii::$app->db->beginTransaction();
    try {
        $this->cancelActiveWager($user, $bonus, $box);

        $box->accepted_time = time();
        $box->status = UserBonus::STATUS_ACTIVE;
        if ($prize === Bonus::GIFT_PRIZE_FUTURE_DEP) {
            $box->wait_dep = true;
        }
        $box->save(false);
        $transaction->commit();
    } catch (\Throwable $e) {
        $transaction->rollBack();
        $this->logError('[GiftBoxDep] activate prize failed for user_bonus ' . $box->id
            . ': ' . $e->getMessage());
        throw $e;
    }

